<h1>Moderar comentarios</h1><form class="filters" method="get"><div class="field"><label for="comment-q">Buscar comentario</label><input id="comment-q" type="search" name="q" value="<?= e($q) ?>"></div><div class="field"><label for="comment-status">Estado</label><select id="comment-status" name="status"><?php foreach (['pendiente', 'aprobado', 'rechazado', 'spam'] as $option): ?><option value="<?= e($option) ?>"<?= $status === $option ? ' selected' : '' ?>><?= e(ucfirst($option)) ?></option><?php endforeach; ?></select></div><button class="button">Filtrar</button></form><?php foreach ($items as $item): ?><article class="panel comment"><h2><?= e($item['name']) ?></h2><p class="muted">En: <?= e($item['title']) ?> · <?= e($item['status']) ?></p><p><?= e($item['content']) ?></p><form class="actions" method="post" action="<?= e(url('admin/comentarios/' . $item['id'])) ?>"><?= csrf() ?><button class="button" name="status" value="aprobado">Aprobar<span class="sr-only"> comentario <?= e($item['id']) ?></span></button><button class="button button--quiet" name="status" value="rechazado">Rechazar<span class="sr-only"> comentario <?= e($item['id']) ?></span></button><button class="button button--danger" name="status" value="spam">Marcar spam<span class="sr-only"> comentario <?= e($item['id']) ?></span></button></form></article><?php endforeach; ?><?php if (!$items): ?><p class="empty">No hay comentarios con este filtro. La conversación está al día.</p><?php endif; ?><?php pagination($result, 'admin/comentarios', compact('status', 'q')); ?>
